package com.example.inventory;

import org.springframework.boot.web.client.RestTemplateBuilder;
import org.springframework.stereotype.Component;
import org.springframework.web.client.HttpServerErrorException;
import org.springframework.web.client.RestTemplate;

@Component
public class InventoryClient {
    private final RestTemplate restTemplate;

    public InventoryClient(RestTemplateBuilder builder) {
        this.restTemplate = builder.rootUri("https://inventory.internal").build();
    }

    public Stock fetch(String sku) {
        try {
            return restTemplate.getForObject("/stocks/{sku}", Stock.class, sku);
        } catch (HttpServerErrorException e) {
            throw new InventoryUnavailableException(sku, e.getStatusCode());
        }
    }
}

package com.example.inventory;

public record Stock(String sku, int quantity) {
}

package com.example.inventory;

import org.springframework.http.HttpStatusCode;

public class InventoryUnavailableException extends RuntimeException {
    public InventoryUnavailableException(String sku, HttpStatusCode status) {
        super("inventory returned " + status + " for " + sku);
    }
}

